const params=new URLSearchParams(location.search);
let theme=params.get('theme')||'light';
document.documentElement.dataset.theme=theme;
window.__prototypeErrors=[];window.addEventListener('error',e=>window.__prototypeErrors.push(e.message));
const initial=params.get('state')||({shelf:'library',compass:'home',control:'running'}[CONCEPT]);
let view=initial==='picker'?'chat':initial;
let category='All',query='',task='Chat',priority='Balanced',selectedFile='Q4_K_M',selectedId='qwen3.5-9b-q4_k_m',operation='running',percent=42,discoverState='',memoryKnown=true;
let installedIds=new Set(['qwen3.5-9b-q4_k_m','qwen2.5-coder-7b-instruct-q4_k_m','llama-3.2-3b-instruct-q4_k_m','clef-flash-q4_k_m','whisper-large-v3-turbo','flux2-klein-4b-q4_0','kokoro-82m-v1.0-q8','qwen3-embedding-0.6b-q8_0']);
let enabledIds=new Set(installedIds),defaults=new Map(),loadedIds=new Set(['qwen3.5-9b-q4_k_m','clef-flash-q4_k_m','whisper-large-v3-turbo']);
const memory={ 'qwen3.5-9b-q4_k_m':9.2,'clef-flash-q4_k_m':8.4,'whisper-large-v3-turbo':2.4 };
const qualificationPending=m=>/qualification.*pending/i.test(m.notes||'');
const kindLabel=m=>m.llmRuntime?.capability==='decision-only'?'Decisions':m.llmRuntime?.capability==='embedding-only'?'Embeddings':({llm:'Chat',stt:'Transcribe',tts:'Speak',image:'Images',video:'Video'}[m.kind]);
const activeCatalog=CATALOG.filter(m=>installedIds.has(m.modelId));
for(const m of activeCatalog)if(!defaults.has(kindLabel(m)))defaults.set(kindLabel(m),m.modelId);
defaults.set('Chat',selectedId);
if(initial==='empty'){installedIds.clear();enabledIds.clear();defaults.clear();loadedIds.clear();}
const find=id=>CATALOG.find(m=>m.modelId===id);
const name=id=>find(id)?.displayName||id;
const bytes=n=>(n/1e9).toFixed(2);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const tag=(s,c='')=>`<span class="tag ${c}">${s}</span>`;
const usedMemory=()=>[...loadedIds].reduce((s,id)=>s+(memory[id]||0),0);
const available=()=>64-28-usedMemory();
const diskUsed=()=>CATALOG.filter(m=>installedIds.has(m.modelId)).reduce((s,m)=>s+m.artifacts.reduce((n,a)=>n+a.expectedSizeBytes/1e9,0),0);
const navItems=()=>CONCEPT==='shelf'?[['library','Library'],['get','Get models'],['running','Running now']]:CONCEPT==='compass'?[['home','Choose a task'],['library','My models'],['running','Mac status']]:[['running','Workspace'],['library','Disk inventory'],['get','Provision model'],['download','Transfers']];
const nav=(cls='')=>`<nav aria-label="Model navigation" class="${cls}">${navItems().map(([v,l])=>btn(l,'go:'+v,'',view===v?'aria-current="page"':'')).join('')}</nav>`;
const top=()=>`<a class="skip" href="#main">Skip to content</a><header class="top"><div class="brand"><span class="brandmark" aria-hidden="true">⌘</span>LocalBase</div>${CONCEPT==='compass'?nav('compass-nav'):''}<div class="top-meta"><span class="status"><i class="dot"></i>M4 Max · connected</span>${btn(theme==='light'?'Dark':'Light','theme','quiet','aria-label="Switch color theme"')}</div></header>`;
const memoryBar=(proposed=0)=>`<div class="meter" aria-hidden="true"><span class="other" style="width:43.75%"></span><span class="model" style="width:${usedMemory()/64*100}%"></span>${proposed?`<span class="proposed" style="width:${Math.min(proposed,available())/64*100}%"></span>`:''}</div><div class="legend"><span>Other apps 28 GiB</span><span>Models ${usedMemory().toFixed(1)} GiB</span><span>${memoryKnown?available().toFixed(1)+' GiB available':'Availability unknown'}</span></div>`;
const controlHead=()=>`<div class="control-head"><div class="between"><span><span class="console-title">Shared memory · M4 Max</span><br><strong class="stat-number">${memoryKnown?available().toFixed(1)+' GiB available':'Refresh memory status'}</strong><span class="muted small"> / 64 GiB</span></span>${btn('Choose for chat','picker','')}</div>${memoryBar()}</div>${nav('tabs')}`;
const footer=()=>`<details class="scenario"><summary>Explore prototype states</summary><div class="cluster">${['picker','library','get','add','download','warning','empty'].map(v=>btn(v==='add'?'File choice':v[0].toUpperCase()+v.slice(1),'go:'+v)).join('')}</div><div class="cluster section">${btn('Empty search','scenario:empty-search')}${btn('Search unavailable','scenario:offline')}${btn('Unknown memory','scenario:unknown')}${btn('Expired session','scenario:session')}${btn('Reset demo','reset')}</div><p class="fine-print section">Concept study. Real catalog and pinned file sizes; simulated installations, memory, timings and transfer controls. No gateway requests. Downloaded files would live on the Mac.</p></details><footer class="app-footer">LocalBase · ${CONCEPT==='shelf'?'Shelf':CONCEPT==='compass'?'Compass':'Control room'} · Round 3</footer>`;
function shell(content){document.body.className=CONCEPT;document.body.innerHTML=`${top()}<div class="notice-bar">Concept preview · simulated Mac state · files download to the Mac</div>${CONCEPT==='control'?controlHead():''}<div class="layout">${CONCEPT==='shelf'?`<aside class="rail">${nav()}<div class="rail-note">TimsExperiments<br>M4 Max · 64 GB<br>Self-hosted gateway</div>${btn('Continue chat','go:chat','quiet chat-nav')}</aside>`:''}<main id="main" tabindex="-1"><div class="content">${CONCEPT==='compass'?nav('mobile-nav tabs'):''}${content}${footer()}</div></main></div><div id="toast" role="status" aria-live="polite"></div><dialog class="picker-dialog" id="picker" aria-labelledby="picker-title"></dialog>`;}
const heading=(title,desc='',action='')=>`<div class="heading ${action?'between':''}"><div><p class="eyebrow">${CONCEPT==='shelf'?'Your model collection':CONCEPT==='compass'?'Start with the job':'Mac workspace'}</p><h1>${title}</h1>${desc?`<p class="intro">${desc}</p>`:''}</div>${action}</div>`;
function row(m,mode='library'){
 const installed=installedIds.has(m.modelId),enabled=enabledIds.has(m.modelId),isDefault=defaults.get(kindLabel(m))===m.modelId;
 const disk=m.artifacts.reduce((s,a)=>s+a.expectedSizeBytes,0)/1e9;
 const label=kindLabel(m),busy=m.modelId==='clef-flash-q4_k_m';
 return `<li class="row"><div class="model-main"><span class="model-icon" aria-hidden="true">${({Chat:'Q',Decisions:'C',Transcribe:'W',Speak:'K',Images:'F',Embeddings:'E',Video:'V'})[label]}</span><div class="wrap"><h3>${esc(m.displayName)}</h3><div class="metadata">${label} · ${disk.toFixed(2)} GB on disk${loadedIds.has(m.modelId)?` · ${memory[m.modelId]} GiB in memory`:''}</div><div class="cluster">${tag(installed?'Installed':'Not installed')}${mode==='get'&&qualificationPending(m)?tag('Qualification pending','amber'):''}${installed?tag(enabled?'Enabled':'Disabled',enabled?'green':''):''}${isDefault?tag(label+' default'):''}${loadedIds.has(m.modelId)?tag(busy?'Running · API request':'Loaded · idle','green'):''}</div></div></div><div class="row-actions">${mode==='get'?btn('Choose file','candidate:'+m.modelId,''):btn('Details','detail:'+m.modelId,'',`aria-label="Manage ${esc(m.displayName)}"`)}</div></li>`;
}
function resources(){return `<div class="panel resource-strip"><div><div class="small muted">Memory available now</div><div class="stat-number">${memoryKnown?available().toFixed(1)+' GiB':'Unknown'}</div>${memoryBar()}</div><div class="disk-summary"><div class="small muted">Model files on the Mac</div><div class="stat-number">${diskUsed().toFixed(1)} GB <span class="small muted">on disk</span></div><p class="small muted">${installedIds.size} installed · 412 GB free on Mac SSD</p>${btn('See running models','go:running','quiet link-button')}</div></div>`;}
function library(){
 if(CONCEPT==='control')return inventory();
 return heading(CONCEPT==='compass'?'Your tools, ready when needed':'Your library','Stored on your Mac. Loads on demand.',btn('Get a model',CONCEPT==='compass'?'go:home':'go:get','primary'))+resources()+`<div class="between section"><h2>${installedIds.size} installed models</h2>${btn('API defaults','go:defaults','quiet')}</div><form class="search" id="library-search"><label for="library-query">Find an installed model</label><input id="library-query" type="search" name="q" value="${esc(query)}" placeholder="Name or task" autocomplete="off"></form><div class="cluster">${['All','Chat','Other tasks'].map(c=>btn(c,'filter:'+c,category===c?'primary':'',`aria-pressed="${category===c}"`)).join('')}</div><ul class="panel list list-panel section" id="library-list">${libraryRows()}</ul>`;
}
function libraryRows(){const rows=CATALOG.filter(m=>installedIds.has(m.modelId)&&(category==='All'||kindLabel(m)===category||(category==='Other tasks'&&kindLabel(m)!=='Chat')||(category==='Audio'&&['Transcribe','Speak'].includes(kindLabel(m))))&&(`${m.displayName} ${kindLabel(m)}`.toLowerCase().includes(query.toLowerCase())));rows.sort((a,b)=>[...installedIds].indexOf(a.modelId)-[...installedIds].indexOf(b.modelId));return rows.length?rows.map(m=>row(m)).join(''):`<li class="empty"><h2>No installed matches</h2><p>Try another name or get a model for this task.</p>${btn('Clear search','clear')}${btn('Get models','go:get','primary')}</li>`;}
function home(){return heading('What do you want to do?','Start with a task. Use a model you have, or find one that suits this Mac.')+`<div class="panel tint between"><div><span class="small muted">Last conversation</span><h3 style="margin-top:8px">${esc(name(selectedId))}</h3><span class="small">Installed · ready for chat</span></div>${btn('Continue','go:chat','primary')}</div><div class="card-grid section">${[['Chat','Write, reason and ask questions'],['Decisions','Choose or score through Clef'],['Transcribe','Turn recordings into text'],['Speak','Read text aloud'],['Images','Generate an image'],['Embeddings','Search and retrieval'],['Video','Generate a video']].map(([t,d],i)=>`<button class="task-card" data-action="task:${t}"><div class="task-index">0${i+1}</div><strong>${t}</strong><span>${d}</span></button>`).join('')}</div><div class="between section"><span class="small muted">Know exactly what you want?</span>${btn('Search by name','go:get','quiet link-button')}</div>`;}
function guide(){return `<div class="journey"><ol class="steps"><li aria-current="step">01 · ${task}</li><li>02 · Pick a model</li><li>03 · Install on Mac</li></ol><div>${heading(task==='Chat'?'What matters for this chat?':`Choose a ${task.toLowerCase()} model`,'Your existing models stay one tap away.')}${['Balanced','Small footprint','More fidelity'].map(p=>btn(`${p}<span>${p==='Balanced'?'A qualified file with a moderate memory footprint':p==='Small footprint'?'Leave more memory for other Mac apps':'Compare larger files; quality gains are unmeasured'}</span> →`,'priority:'+p,'priority-choice'))}${btn('Back to tasks','go:home','quiet')}</div></div>`;}
function recommend(){const options=CATALOG.filter(m=>kindLabel(m)===task);const recommended=(task==='Chat'&&priority==='Small footprint'?options.find(m=>m.modelId==='qwen3.5-4b-q4_k_m'):options.find(m=>m.modelId==='qwen3.8-27b-q4_k_m'))||options[0];return `<div class="journey"><ol class="steps"><li>01 · ${task}</li><li aria-current="step">02 · ${priority}</li><li>03 · Install on Mac</li></ol><div>${heading(`A model for ${task.toLowerCase()}`,'A starting point based on runtime support and memory, not an unmeasured quality score.')}<div class="panel lead-option">${tag(qualificationPending(recommended)?'Qualification pending':'Qualified LocalBase entry',qualificationPending(recommended)?'amber':'green')}<h2>${esc(recommended.displayName)}</h2><p class="muted">${recommended.quant} · ${recommended.storageGb} GB catalog size${recommended.modelId==='qwen3.8-27b-q4_k_m'?' · about 23 GiB estimated at 8k context':''}</p><p class="small">${esc(recommended.catch)}</p>${btn(installedIds.has(recommended.modelId)?'Open installed model':'Review download','candidate:'+recommended.modelId,'primary')}</div><h3 class="section">Already on your Mac</h3><ul class="list">${options.filter(m=>installedIds.has(m.modelId)).map(m=>row(m)).join('')||'<li class="muted small">No model for this task installed yet.</li>'}</ul>${btn('Change priorities','go:guide','quiet')}${btn('Search all models','go:get','quiet')}</div></div>`;}
function inventory(){return heading('Disk inventory','Stored files are separate from what is running.',btn('Provision model','go:get','primary'))+`<div class="panel"><div class="between"><div><span class="small muted">Model files</span><div class="stat-number">${diskUsed().toFixed(1)} GB</div></div><span class="small muted">412 GB free on Mac SSD</span></div><div class="between section"><h2>Largest files first</h2>${btn('API defaults','go:defaults','quiet')}</div><div class="ledger head"><span>Model / task</span><span>Disk</span><span>Memory now</span><span>Manage</span></div>${CATALOG.filter(m=>installedIds.has(m.modelId)).sort((a,b)=>b.storageGb-a.storageGb).map(m=>`<div class="ledger"><div class="wrap"><strong>${esc(m.displayName)}</strong><span class="muted">${kindLabel(m)} · ${enabledIds.has(m.modelId)?'enabled':'disabled'}</span><span class="mobile-inventory-stat muted">${(m.artifacts.reduce((s,a)=>s+a.expectedSizeBytes,0)/1e9).toFixed(2)} GB disk · ${loadedIds.has(m.modelId)?memory[m.modelId]+' GiB memory':'not loaded'}</span></div><span class="hide-narrow">${(m.artifacts.reduce((s,a)=>s+a.expectedSizeBytes,0)/1e9).toFixed(2)} GB</span><span class="hide-narrow">${loadedIds.has(m.modelId)?memory[m.modelId]+' GiB':'Not loaded'}</span>${btn('Manage','detail:'+m.modelId,'',`aria-label="Manage ${esc(m.displayName)}"`)}</div>`).join('')}</div>`;}
function running(){return heading(CONCEPT==='control'?'What is using the Mac?':'Running now','Requests from chat and API clients share this memory.',CONCEPT==='control'?'':btn('Choose for chat','picker',''))+`<div class="${CONCEPT==='control'?'workspace':'stack'}"><section class="panel"><div class="between"><h2>${loadedIds.size} models in memory</h2>${tag('Live state · demo','green')}</div>${CONCEPT!=='control'?memoryBar():''}${[...loadedIds].map(id=>`<article class="lane"><div class="between"><div class="wrap"><h3>${esc(name(id))}</h3><p class="muted small">${memory[id]} GiB · ${id.includes('clef')?'API client · 1 request in progress':'Idle · can unload'}</p><div class="cluster">${tag(id.includes('clef')?'Busy':'Loaded, idle',id.includes('clef')?'amber':'green')}${tag('Files remain installed')}</div></div>${btn(id.includes('clef')?'In use':'Unload','unload:'+id,'',id.includes('clef')?'disabled':'')}</div></article>`).join('')||'<p class="muted section">Nothing loaded. Enabled models can load on the next request.</p>'}</section><aside class="panel tint"><p class="eyebrow">Next request</p><h2>Plan before loading</h2><p class="small">A larger chat model competes with Clef and the other apps on your Mac.</p>${btn('Plan Qwen3.8 load','go:warning','primary')}<hr class="divider"><p class="small muted">Unload frees memory.<br>Disable stops new requests.<br>Remove deletes files.</p>${btn('Review installed files','go:library','quiet link-button')}</aside></div>`;}
function getModels(){
 let rows=CATALOG.filter(m=>!query||(`${m.displayName} ${kindLabel(m)}`).toLowerCase().includes(query.toLowerCase()));
 const featured=['qwen3.8-27b-q4_k_m','clef-flash-q4_k_m','whisper-large-v3-turbo','flux2-klein-4b-q4_0','qwen3-embedding-0.6b-q8_0','kokoro-82m-v1.0-q8','wan2.1-t2v-1.3b-q8_0'];
 if(!query)rows=featured.map(find).filter(Boolean);
 return heading(CONCEPT==='control'?'Provision a model':'Find your next model',CONCEPT==='compass'?'Search directly, or go back and start with a task.':'Qualified entries and Hugging Face, in one place.')+`<form id="discovery-search" class="search"><label for="discover-query">Model name or Hugging Face URL</label><div class="cluster" style="flex-wrap:nowrap"><input id="discover-query" type="search" name="q" value="${esc(query)}" placeholder="Try Qwen3.8 or paste a repository URL" autocomplete="off">${btn('Search','search','primary')}</div></form><div id="discovery-results">${discoveryResults(rows)}</div>`;
}
function discoveryResults(rows){if(discoverState==='offline')return `<div class="callout warning" role="alert"><strong>Hugging Face could not be reached</strong><p>Your search is saved. Installed models are still available.</p>${btn('Retry search','retry-search')}${btn('Go to library','go:library','quiet')}</div>`;if(discoverState==='empty-search'||!rows.length)return `<div class="panel empty"><h2>No models found</h2><p>Try a shorter name, or paste the full repository URL.</p>${btn('Clear search','clear','primary')}</div>`;return `<div class="between section"><h2>${query?'Search results':'Start with a LocalBase entry'}</h2>${tag('Catalog entries, then community')}</div><p class="fine-print">Qualified means this specific file and runtime profile. Other files require a compatibility check.</p><ul class="panel list list-panel">${rows.slice(0,8).map(m=>row(m,'get')).join('')}</ul>${!query||query.toLowerCase().includes('qwen3.8')?`<div class="callout section"><strong>From Hugging Face</strong><p class="small muted">bartowski/Qwen3.8-27B-GGUF · many file variants<br>Source revision pinned to match the catalog.</p>${btn('Compare files','candidate:qwen3.8-27b-q4_k_m','quiet link-button')}</div>`:''}`;}
let candidateId='qwen3.8-27b-q4_k_m';
const quantName=f=>f.name.replace('Qwen3.8-27B-','').replace('.gguf','');
const common=['Q4_K_M','Q4_K_S','Q5_K_M','Q6_K','Q8_0','IQ4_XS','Q3_K_M','Q3_K_S','Q2_K','IQ2_XXS'];
const commonFiles=common.map(q=>FILES.find(f=>quantName(f)===q)).filter(Boolean);
const extraFiles=FILES.filter(f=>!common.includes(quantName(f))&&!f.name.includes('/')&&!f.name.includes('imatrix')&&!f.name.startsWith('mmproj'));
const fileOption=f=>{const q=quantName(f),qualified=q==='Q4_K_M';return `<label class="file-option"><input type="radio" name="file" value="${esc(q)}" ${selectedFile===q?'checked':''}><span class="file-info"><strong>${q==='Q4_K_M'?'Balanced · qualified':q==='Q8_0'?'Larger file · check memory':q==='IQ4_XS'?'Smaller alternative':q}</strong><small class="wrap">${esc(f.name)}</small><small>${qualified?'Catalog-pinned · about 23 GiB estimated at 8k context':'Hugging Face · compatibility unverified'}</small></span><span class="file-size">${bytes(f.bytes)} GB</span></label>`;};
function add(){const m=find(candidateId),isQ=m.modelId==='qwen3.8-27b-q4_k_m';return `<p class="flow-label">${CONCEPT==='compass'?'Task → Recommendation → File → Install':CONCEPT==='control'?'Provision → Artifact → Resource review':'Get models → Model → Choose a file'}</p>${heading(esc(m.displayName),isQ?'One model. Choose the file that suits this Mac.':`${kindLabel(m)} · ${esc(m.catch)}`)}<div class="detail-grid"><section>${isQ?`<div class="callout"><strong>Start with the qualified file</strong><p class="small" style="margin:8px 0 0">Q4_K_M is the catalog choice. Larger files use more disk and memory; their quality gains have not been measured here.</p></div><fieldset class="section"><legend>File to download · 10 common choices</legend><div class="choice-list">${commonFiles.slice(0,3).map(fileOption).join('')}</div><details><summary>Compare the other 7 common files</summary><div class="choice-list">${commonFiles.slice(3).map(fileOption).join('')}</div></details><details><summary>More repository variants and weight shards</summary><div class="choice-list">${extraFiles.map(fileOption).join('')}</div><p class="fine-print">The bf16 weight set has two shards and would require one grouped download. It is unavailable in this concept's qualified runtime profile. Projectors and imatrix files are supplementary and cannot be selected alone.</p><p class="fine-print">bf16 shards: ${FILES.filter(f=>f.name.includes('/')).map(f=>`${esc(f.name)} · ${bytes(f.bytes)} GB`).join('<br>')}</p></details></fieldset>`:`<div class="panel"><h2>${qualificationPending(m)?'Catalog file set':'Qualified file set'}</h2><p class="muted small">${m.quant} · ${m.artifacts.length} ${m.artifacts.length===1?'file':'files'} · ${m.artifacts.reduce((s,a)=>s+a.expectedSizeBytes/1e9,0).toFixed(2)} GB total</p>${m.artifacts.map(a=>`<p class="fine-print wrap">${esc(a.filename)}<br>${bytes(a.expectedSizeBytes)} GB · ${a.role}</p>`).join('')}<p class="small">${esc(m.notes)}</p></div>`}<div id="file-warning">${fileWarning()}</div><div class="actions">${btn('Review download','review-file','primary')}${btn('Back to search','go:get','')}</div></section><aside class="panel"><h3>Your Mac</h3><div class="summary-pair"><span>Memory</span><strong>64 GiB shared</strong></div><div class="summary-pair"><span>Available now</span><strong>${memoryKnown?available().toFixed(1)+' GiB':'Unknown'}</strong></div><div class="summary-pair"><span>Disk free</span><strong>412 GB</strong></div><p class="fine-print section">Memory estimates vary with context, image size and other workloads. A file can fit this Mac without fitting right now.</p><details><summary class="small">Source and trust</summary><p class="fine-print wrap">${esc(m.source)}<br>Revision ${esc(m.repositoryRevision)}<br>${esc(m.catch)}</p></details></aside></div>`;}
function fileWarning(){return selectedFile==='Q4_K_M'?`<p class="fine-print">Fits the 64 GiB host estimate. ${memoryKnown?available().toFixed(1)+' GiB available now; loading needs another memory check.':'Current memory unknown; loading is blocked until refreshed.'}</p>`:`<div class="callout warning" role="alert"><strong>Alternative file, not qualified yet</strong><p class="small">${selectedFile} has not been qualified in LocalBase. Review memory and runtime support before enabling it.</p></div>`;}
function review(){const m=find(candidateId),f=FILES.find(f=>quantName(f)===selectedFile);const gb=m.modelId==='qwen3.8-27b-q4_k_m'?bytes(f.bytes):m.artifacts.reduce((s,a)=>s+a.expectedSizeBytes/1e9,0).toFixed(2);return heading('Download to your Mac',esc(m.displayName))+`<div class="panel progress-shell"><h2>${m.modelId.includes('qwen3.8')?selectedFile:m.quant}</h2><div class="summary-pair"><span>Download</span><strong>${gb} GB</strong></div><div class="summary-pair"><span>Disk remaining after download</span><strong>${(412-Number(gb)).toFixed(1)} GB</strong></div><div class="summary-pair"><span>When complete</span><strong>Installed, disabled</strong></div><p class="small muted section">This downloads files only. Enabling and loading are separate actions. API defaults stay unchanged.</p>${selectedFile!=='Q4_K_M'&&m.modelId.includes('qwen3.8')?'<p class="callout warning small">Experimental file. Compatibility is unverified.</p>':''}<div class="actions">${btn('Start download','start-download','primary')}${btn('Change file','go:add')}${btn('Check memory','go:warning','quiet')}</div></div>`;}
function download(){const m=find(candidateId),f=FILES.find(f=>quantName(f)===selectedFile),total=m.modelId.includes('qwen3.8')?Number(bytes(f.bytes)):m.artifacts.reduce((s,a)=>s+a.expectedSizeBytes/1e9,0);const labels={running:'Downloading on your Mac',paused:'Download paused',failed:'Download interrupted',verifying:'Verifying files',complete:'Installed on your Mac',cancelled:'Download canceled',enabled:'Enabled for requests'};
 const ongoing=['running','paused','failed'].includes(operation);
 return heading('Downloads','You can leave this page. The Mac owns the transfer.')+`<div class="panel progress-shell"><div class="between"><div class="wrap"><h2>${esc(m.displayName)}</h2><p class="muted small">${m.modelId.includes('qwen3.8')?selectedFile:m.quant} · ${total.toFixed(2)} GB · Mac SSD</p></div>${tag(operation==='complete'?'Installed':'Transfer',operation==='failed'?'amber':'green')}</div><hr class="divider"><p class="eyebrow">${labels[operation]}</p>${ongoing?`<div class="progress-big">${percent}%</div><progress value="${percent}" max="100" aria-label="Model download">${percent}%</progress><div class="between small muted"><span>${(total*percent/100).toFixed(2)} of ${total.toFixed(2)} GB</span><span>${operation==='running'?'32 MB/s · ~5 min left':operation==='paused'?'Ready to resume':'Connection lost'}</span></div>`:`<h2>${operation==='verifying'?'Checking artifact hashes':operation==='cancelled'?'No model installed':operation==='enabled'?'Ready for the next request':'Files verified. Enable when ready.'}</h2>`}<p class="small muted section">${operation==='running'?'Downloading does not load this model or change your defaults.':operation==='failed'?'Retry keeps the same file choice. Resume support needs a backend contract.':operation==='complete'?'Disabled for requests. No memory has been allocated.':operation==='enabled'?'Loads on demand, after a fresh memory check. API defaults stay unchanged.':operation==='verifying'?'Verification is part of installation. The model is not ready yet.':operation==='cancelled'?'Partial-file cleanup must follow server policy.':'This pause is a concept interaction; production support is not assumed.'}</p><div class="actions">${operation==='running'?btn('Pause','operation:paused')+btn('Cancel download','operation:cancelled','quiet'):operation==='paused'?btn('Resume','operation:running','primary')+btn('Cancel download','operation:cancelled','quiet'):operation==='failed'?btn('Retry download','operation:running','primary'):operation==='verifying'?btn('Finish verification','operation:complete','primary'):operation==='complete'?btn('Enable for requests','enable-downloaded','primary'):operation==='enabled'?btn('Open model details','detail:'+candidateId,'primary'):btn('Choose a model','go:get','primary')}${btn('View library','go:library','quiet')}</div><div class="queue-item"><p class="small muted">${operation==='enabled'?'Enabled · loads on demand':operation==='complete'?'Installed · disabled':operation==='verifying'?'Download complete · verification pending':'Next: verify files → installed, disabled'}</p></div><details><summary class="fine-print">Simulate a transfer result</summary><div class="cluster">${btn('Advance to 68%','advance')}${btn('Network error','operation:failed')}${btn('Download finished','operation:verifying')}</div></details></div>`;
}
function warning(){const larger=selectedFile==='Q8_0';return heading(CONCEPT==='control'?'Review a load plan':'There is not room right now',`Qwen3.8 27B · ${larger?'Q8_0':'Q4_K_M'} · estimates for an 8k context`)+`<div class="${CONCEPT==='control'?'workspace':'detail-grid'}"><section class="panel"><div class="callout warning"><strong>${memoryKnown?'Loading would exceed the current budget':'Current memory availability is unknown'}</strong><p class="small">${memoryKnown?`${larger?'35':'23'} GiB estimated peak + 6 GiB reserve. Only ${available().toFixed(1)} GiB is available. The model fits this Mac's capacity, but other workloads are using it.`:'Refresh the Mac status before loading. Downloading the files can continue.'}</p></div><div class="section"><div class="summary-pair"><span>Model peak, estimated</span><strong>${larger?'35':'23'} GiB</strong></div><div class="summary-pair"><span>Safety reserve</span><strong>6 GiB</strong></div><div class="summary-pair"><span>Available now</span><strong>${memoryKnown?available().toFixed(1)+' GiB':'Unknown'}</strong></div></div>${memoryBar()}<h3 class="section">Keep current work safe</h3><p class="small muted">Clef has an API request in progress. Unloading one idle chat model would leave too little headroom. Wait, use an installed model, or download without loading.</p>${CONCEPT==='control'?`<div class="panel section"><h3>Proposed changes</h3><p class="small">Load Qwen3.8 only after a fresh capacity check. No running request is interrupted.</p><div class="cluster">${tag('Clef stays running','green')}${tag('No automatic eviction')}</div></div>`:''}<div class="actions">${btn('Download files only','start-download','primary')}${btn('Use current chat model','go:chat')}${btn('Refresh memory','refresh-memory','quiet')}</div></section><aside class="panel"><h3>What you can do</h3><p class="small muted">A smaller file may use less memory, but its runtime support still needs checking.</p>${btn('Compare file options','go:add','')}<hr class="divider"><p class="fine-print">Simulated memory. These are estimates, not measurements or a reservation. The server must check again at load time.</p></aside></div>`;}
function empty(){return heading('Your Mac is ready','Start with one model for the job you need.')+`<div class="panel empty"><div class="empty-icon" aria-hidden="true">＋</div><h2>No models installed yet</h2><p>Choose a qualified starting point. Files are stored on the Mac and load only when needed.</p>${btn(CONCEPT==='compass'?'Choose your first task':'Get your first model',CONCEPT==='compass'?'go:home':'go:get','primary')}<div class="small muted section">0 GB of model files · 412 GB free on Mac SSD</div></div>`;}
function chat(){return `<div class="chat"><div><div class="between"><p class="eyebrow">Conversation · planning a day out</p>${btn('Models',CONCEPT==='compass'?'go:home':'go:library','quiet')}</div><div class="message user">Help me plan a day in Chicago with time for the architecture boat tour.</div><div class="message"><h2>A day by the river</h2><p class="muted">Start with coffee in the Loop, take a late-morning river cruise, then walk north for lunch.</p></div></div><div class="composer"><label class="small muted" for="draft">Message</label><textarea id="draft" rows="2">Keep the afternoon flexible.</textarea><div class="between">${btn(esc(name(selectedId))+' ▾','picker','quiet',`id="picker-trigger" ${CONCEPT==='compass'?'':'aria-haspopup="dialog"'}`)}${btn('Send','send','primary')}</div></div></div>`;}
function picker(){if(CONCEPT==='compass'){view='choose';render();return;}const dialog=document.querySelector('#picker');const candidates=CATALOG.filter(m=>installedIds.has(m.modelId)&&enabledIds.has(m.modelId)&&kindLabel(m)==='Chat').sort((a,b)=>Number(b.modelId===selectedId)-Number(a.modelId===selectedId));dialog.innerHTML=`<div class="dialog-head"><div class="between"><h2 id="picker-title">${CONCEPT==='control'?'Choose for this request':'Choose a chat model'}</h2>${btn('✕','close-picker','quiet','aria-label="Close model picker"')}</div><p class="small muted section" style="margin-top:12px">This conversation only. API defaults stay unchanged.</p></div><div class="dialog-body">${CONCEPT==='control'?`<div class="callout small">${available().toFixed(1)} GiB available now. Reuse an idle model to avoid another load.</div>`:''}<div class="small muted section">${CONCEPT==='control'?'Loaded / available on demand':'Recent and installed'}</div>${candidates.map(m=>btn(`<span class="wrap"><strong>${esc(m.displayName)}</strong><small>${loadedIds.has(m.modelId)?`${memory[m.modelId]} GiB · loaded and idle`:'Installed · loads on demand'}</small></span><span>${m.modelId===selectedId?'✓':CONCEPT==='control'?'Use':'→'}</span>`,'select:'+m.modelId,'pick-option',`aria-label="Choose ${esc(m.displayName)}"`)).join('')}<div class="callout small section">Clef and embeddings are available to API clients, outside the chat picker.</div><div class="actions">${btn('Get another model','picker-add','quiet link-button')}${btn('View library','picker-library','quiet')}</div></div>`;dialog.showModal();dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const controls=[...dialog.querySelectorAll('button,input,a[href],select,textarea')].filter(n=>!n.disabled&&n.getClientRects().length);const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});dialog.addEventListener('close',()=>document.querySelector('#picker-trigger')?.focus(),{once:true});}
function choose(){const list=CATALOG.filter(m=>installedIds.has(m.modelId)&&enabledIds.has(m.modelId)&&kindLabel(m)==='Chat');return heading('Which model for this chat?','Pick a recent model or choose by priority.')+`<div class="inline-choice"><div class="panel tint primary-choice"><p class="eyebrow">Continue with the loaded model</p><h2>${esc(name(selectedId))}</h2><p class="small muted">Keeps your draft. Leaves gateway defaults alone.</p>${btn('Use this model','select:'+selectedId,'primary')}</div><div class="panel"><h3>Other installed choices</h3>${list.filter(m=>m.modelId!==selectedId).map(m=>btn(`<span class="wrap"><strong>${esc(m.displayName)}</strong><small>Loads on demand</small></span><span>→</span>`,'select:'+m.modelId,'pick-option')).join('')}</div></div><div class="between section"><span class="small muted">Need something different?</span>${btn('Choose by task','task:Chat','quiet link-button')}</div>${btn('Back to conversation','go:chat','quiet')}`;}
function detail(){const m=find(candidateId),isDefault=defaults.get(kindLabel(m))===candidateId;return heading(esc(m.displayName),`${kindLabel(m)} · ${m.quant}`)+`<div class="panel"><div class="cluster">${tag(installedIds.has(candidateId)?'Installed':'Not installed')}${tag(enabledIds.has(candidateId)?'Enabled for requests':'Disabled')}${isDefault?tag(kindLabel(m)+' API default','green'):''}</div><p class="muted section">${esc(m.catch)}</p><div class="summary-pair"><span>Files on disk</span><strong>${m.artifacts.reduce((s,a)=>s+a.expectedSizeBytes/1e9,0).toFixed(2)} GB</strong></div><div class="summary-pair"><span>Memory now</span><strong>${loadedIds.has(candidateId)?memory[candidateId]+' GiB':'Not loaded'}</strong></div><div class="actions">${installedIds.has(candidateId)?btn(enabledIds.has(candidateId)?'Disable for requests':'Enable for requests','toggle-enable'):btn('Choose download','go:add','primary')}${btn('Set '+kindLabel(m).toLowerCase()+' API default','set-default','',!enabledIds.has(candidateId)?'disabled':'')}${loadedIds.has(candidateId)?btn('Unload','unload:'+candidateId,'',candidateId.includes('clef')?'disabled':''):''}${installedIds.has(candidateId)?btn('Remove files','remove','quiet'):''}</div><p class="fine-print section">Default is used when an API request omits its model. Conversation choice is separate. ${isDefault?'Choose a replacement default before disabling or removing.':''}</p></div>${btn('Back to library','go:library','quiet section')}`;}
function defaultsView(){return heading('API defaults','Used when a client leaves the model unspecified. Your conversation can use a different model.')+`<div class="panel">${['Chat','Decisions','Embeddings','Transcribe','Speak','Images','Video'].map(k=>`<div class="row"><div><h3>${k}</h3><p class="small muted" style="margin:0">${defaults.has(k)?esc(name(defaults.get(k))):'No default configured'}</p></div>${defaults.has(k)?btn('Change','default-for:'+k):btn('Get model','task:'+k)}</div>`).join('')}</div>`;}
function session(){return heading('Reconnect to your Mac','Your Cloudflare Access session needs renewal.')+`<div class="panel"><h2>Your download stays on the Mac</h2><p class="muted">Sign in, then refresh the operation state. Do not start a duplicate transfer.</p><div class="actions">${btn('Simulate sign in','recover-session','primary')}${btn('Back to library','go:library')}</div><p class="fine-print section">Prototype recovery only. No real authentication request is made.</p></div>`;}
function render(focus=false){const pages={home,guide,recommend,library,running,get:getModels,add,review,download,warning,empty,chat,choose,detail,defaults:defaultsView,session};shell((pages[view]||library)());if(view==='chat')document.querySelector('#draft').value=preservedDraft;if(focus)document.querySelector('h1, #main').focus?.();}
function go(v){if(v==='warning')candidateId='qwen3.8-27b-q4_k_m';if(v==='empty'){installedIds.clear();enabledIds.clear();defaults.clear();loadedIds.clear();}if(v==='picker'){view='chat';render();picker();return;}view=v;query='';category='All';discoverState='';try{history.replaceState(null,'',`?state=${v}&theme=${theme}`);}catch{}render();document.querySelector('main').focus({preventScroll:true});window.scrollTo(0,0);}
function toast(message){const e=document.querySelector('#toast');e.className='toast';e.textContent=message;setTimeout(()=>{if(e.isConnected){e.className='';e.textContent='';}},4500);}
let preservedDraft='Keep the afternoon flexible.';
document.addEventListener('input',e=>{if(e.target.id==='draft')preservedDraft=e.target.value;if(e.target.id==='library-query'){query=e.target.value;document.querySelector('#library-list').innerHTML=libraryRows();}});
document.addEventListener('change',e=>{if(e.target.name==='file'){selectedFile=e.target.value;document.querySelector('#file-warning').innerHTML=fileWarning();}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='discovery-search')search();});
function search(){query=document.querySelector('#discover-query').value;discoverState='';document.querySelector('#discovery-results').innerHTML='<p role="status" class="muted section">Searching qualified entries and Hugging Face…</p>';setTimeout(()=>{const url=query.includes('huggingface.co/');if(url){query='Qwen3.8';document.querySelector('#discover-query').value=query;}const rows=CATALOG.filter(m=>(m.displayName+' '+kindLabel(m)).toLowerCase().includes(query.toLowerCase()));document.querySelector('#discovery-results').innerHTML=discoveryResults(rows);},400);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;const [a,...parts]=action.split(':');const val=parts.join(':');
 if(a==='go'){go(val);return;}if(a==='picker'){picker();return;}if(a==='close-picker'){document.querySelector('#picker').close();return;}
 if(a==='theme'){theme=theme==='light'?'dark':'light';const wasOpen=document.querySelector('#picker').open;document.documentElement.dataset.theme=theme;render();if(wasOpen)picker();return;}
 if(a==='select'){selectedId=val;go('chat');document.querySelector('#draft').value=preservedDraft;document.querySelector('#picker-trigger').focus();toast('Changed for this conversation. API defaults unchanged.');return;}
 if(a==='picker-add'||a==='picker-library'){document.querySelector('#picker').close();go(a==='picker-add'?'get':'library');return;}
 if(a==='filter'){category=val;render();return;}if(a==='clear'){query='';discoverState='';render();return;}
 if(a==='task'){task=val;go('guide');return;}if(a==='priority'){priority=val;go('recommend');return;}
 if(a==='candidate'){candidateId=val;selectedFile='Q4_K_M';go(installedIds.has(val)?'detail':'add');return;}
 if(a==='detail'){candidateId=val;go('detail');return;}if(a==='review-file'){go('review');return;}
 if(a==='start-download'){operation='running';percent=42;go('download');toast('Download started on the Mac.');return;}
 if(a==='operation'){operation=val;if(val==='complete'){if(candidateId.includes('qwen3.8')&&selectedFile!=='Q4_K_M'&&!candidateId.includes('@')){const base=find(candidateId),file=FILES.find(f=>quantName(f)===selectedFile);candidateId=base.modelId+'@'+selectedFile;CATALOG.push({...base,modelId:candidateId,displayName:base.displayName+' · '+selectedFile,quant:selectedFile,storageGb:file.bytes/1e9,notes:'Experimental Hugging Face artifact; compatibility check required',catch:'Compatibility unverified. Enabling is blocked in this concept.',artifacts:[{filename:file.name,sourcePath:file.name,expectedSizeBytes:file.bytes,role:'primary'}]});}installedIds.add(candidateId);}go('download');toast({running:'Download resumed',failed:'Download failed. Retry is available.',verifying:'Download complete. Verifying files.',complete:'Installed. Disabled for requests.',cancelled:'Download canceled',paused:'Download paused'}[val]);return;}
 if(a==='advance'){percent=68;render();toast('Download progress 68%');return;}
 if(a==='enable-downloaded'){if(candidateId.includes('qwen3.8')&&selectedFile!=='Q4_K_M'){toast('Compatibility check required before enabling this file.');return;}enabledIds.add(candidateId);operation='enabled';render();toast('Enabled for requests. Loads on demand.');return;}
 if(a==='unload'){loadedIds.delete(val);render();toast('Memory released. Files remain installed.');return;}
 if(a==='refresh-memory'){memoryKnown=true;render();toast('Status refreshed. Clef is still busy; no request was interrupted.');return;}
 if(a==='toggle-enable'){if(candidateId.includes('@')){toast('Compatibility check required before enabling this file.');return;}if(defaults.get(kindLabel(find(candidateId)))===candidateId&&enabledIds.has(candidateId)){toast('Choose a replacement API default before disabling.');return;}enabledIds.has(candidateId)?enabledIds.delete(candidateId):enabledIds.add(candidateId);render();toast('Request availability updated.');return;}
 if(a==='set-default'){defaults.set(kindLabel(find(candidateId)),candidateId);render();toast('API default updated for '+kindLabel(find(candidateId)).toLowerCase()+'.');return;}
 if(a==='default-for'){category=val;go('library');category=val;render();return;}
 if(a==='remove'){if(defaults.get(kindLabel(find(candidateId)))===candidateId){toast('Choose a replacement API default before removing.');return;}view='confirm-remove';shell(heading('Remove these files?',esc(name(candidateId)))+`<div class="panel"><p>Deleting files reclaims disk space. This cannot be undone without downloading again.</p><div class="actions">${btn('Keep files','go:detail','primary')}${btn('Remove from Mac','confirm-remove')}</div></div>`);return;}
 if(a==='confirm-remove'){installedIds.delete(candidateId);enabledIds.delete(candidateId);loadedIds.delete(candidateId);go('library');toast('Files removed from the Mac.');return;}
 if(a==='scenario'){if(val==='unknown'){memoryKnown=false;go('warning');}else if(val==='session'){go('session');}else{go('get');discoverState=val;render();}return;}
 if(a==='recover-session'){go('download');toast('Session restored. Operation reconnected.');return;}
 if(a==='retry-search'){discoverState='';render();return;}if(a==='search'){search();return;}if(a==='send'){toast('Concept preview. Message retained; no model runs.');return;}if(a==='reset'){location.search='?theme='+theme;}
});
render();if(initial==='picker')picker();
